    inputSchema: {
      type: 'object',
      properties: {
        text: { type: 'string', description: 'The text to transform.' },
        mode: { type: 'string', enum: ['uppercase', 'lowercase', 'slug'], description: 'Transform mode.' },
        trim: { type: 'boolean', default: true, description: 'Whether to trim whitespace before transforming. Defaults to true.' }
      },
      required: ['text', 'mode'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
