  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  const { text, mode, trim = true } = args;
  if (typeof text !== 'string') {
    throw new Error('Invalid arguments: text must be a string');
  }
  if (mode !== 'uppercase' && mode !== 'lowercase' && mode !== 'slug') {
    throw new Error('Invalid arguments: mode must be uppercase, lowercase, or slug');
  }
  if (typeof trim !== 'boolean') {
    throw new Error('Invalid arguments: trim must be a boolean');
  }
  // check extra keys
  const allowed = new Set(['text', 'mode', 'trim']);
  for (const k of Object.keys(args)) {
    if (!allowed.has(k)) {
      throw new Error(`Invalid arguments: unexpected property '${k}'`);
    }
  }

  let out = text;
  if (trim) out = out.trim();
  if (mode === 'uppercase') out = out.toUpperCase();
  else if (mode === 'lowercase') out = out.toLowerCase();
  else if (mode === 'slug') {
    out = out.toLowerCase();
    out = out.replace(/[^a-z0-9]+/g, '-');
    out = out.replace(/^-+|-+$/g, '');
  }

  return { content: [{ type: 'text', text: out }] };
}
